//! The code `rustorb-idl -brust` generates for `idl/RustMapping.idl`
//! (checked in as `generated/rust_mapping.rs`, regenerated by
//! `generate-rust.sh`): values, TypeCodes and anys, and calls through
//! the generated stubs and skeletons over TCP.

#[allow(dead_code)]
#[path = "generated/rust_mapping.rs"]
mod rust_mapping_idl;

use std::sync::{Arc, Mutex};

use rustorb_core::idl::{self, IdlType};
use rustorb_core::{
    Any, EndpointAddr, Fixed, ObjectRef, Orb, OrbOptions, Servant, SystemException,
    SystemExceptionKind, TCKind,
};

use rust_mapping_idl::rust_mapping::{self as m, *};

fn server_orb() -> Orb {
    Orb::with_options(OrbOptions {
        endpoints: vec![EndpointAddr {
            host: "127.0.0.1".into(),
            port: 0,
        }],
        ..OrbOptions::default()
    })
    .unwrap()
}

/// The same reference through another ORB, so that calls go over TCP.
fn remote(client: &Orb, server: &Orb, obj: &ObjectRef) -> ObjectRef {
    client
        .string_to_object(&server.object_to_string(Some(obj)).unwrap())
        .unwrap()
        .unwrap()
}

#[test]
fn names_and_constants() {
    assert_eq!(m::C_SHORT, -3);
    assert_eq!(m::C_MIN, i32::MIN);
    assert_eq!(m::C_ULONGLONG, 18_000_000_000_000_000_000);
    assert_eq!(m::C_DOUBLE, 0.25);
    assert_eq!(m::C_STRING, "abcd\n");
    assert_eq!(m::C_EXPR, (1 << 21) - 3);
    assert_eq!(m::MAX_COUNT, 5);
    assert_eq!(m::C_ENUM, Fruit::Banana);
    assert_eq!(m::c_fixed(), "12.5".parse::<Fixed>().unwrap());
    assert_eq!(m::base::BASE_CONST, 7);
    assert_eq!(m::inner::INNER_NAME, "inner");
    assert_eq!(m::REOPENED, 1);
    assert_eq!(rust_mapping_idl::GLOBAL_LIMIT, 10);
    assert_eq!(
        Fruit::VALUES,
        [Fruit::Apple, Fruit::Banana, Fruit::CherryPie]
    );
    assert_eq!(Fruit::from_u32(2), Some(Fruit::CherryPie));
    assert_eq!(Pair::REPOSITORY_ID, "IDL:rustorb.org/RustMapping/Pair:1.0");
    let _: m::outer::Mode = m::outer::Mode::Off;
    let _: m::Count2 = 3i32;
}

fn round_trip<T: IdlType>(v: &T::Borrowed) -> Result<T::Rust, SystemException> {
    let any = Any::insert::<T>(v)?;
    Ok(any.extract::<T>().expect("the same type"))
}

fn holder() -> Holder {
    Holder {
        numbers: [1, 2, 3],
        pairs: vec![Pair {
            first: 1,
            second: 2,
        }],
        cells: [[1, 2], [3, 4]],
        tag: "tag".into(),
        bounded: vec![1, 2, 3],
        extra: Any::from(5i32),
        target: None,
        price: "-123.45".parse().unwrap(),
        wide: "wïde".into(),
        letter: 'λ',
        ascii: 'a',
        data: vec![0, 255],
        names: vec!["α".into(), "β".into()],
        r#type: 9,
        self_: true,
        camel_case_name: "x".into(),
    }
}

#[test]
fn values_round_trip() {
    let h = holder();
    assert_eq!(round_trip::<Holder>(&h).unwrap(), h);

    let tree = Tree {
        label: "root".into(),
        children: vec![Tree {
            label: "leaf".into(),
            children: vec![],
        }],
    };
    assert_eq!(round_trip::<Tree>(&tree).unwrap(), tree);
    let node = Node::Branch(vec![Node::Leaf(1), Node::Branch(vec![])]);
    assert_eq!(round_trip::<Node>(&node).unwrap(), node);
    assert_eq!(
        Node::type_code().member_type(1).unwrap().kind(),
        TCKind::Sequence
    );

    for u in [ByBool::Yes(1), ByBool::No("n".into())] {
        assert_eq!(round_trip::<ByBool>(&u).unwrap(), u);
    }
    for u in [ByChar::A(1), ByChar::Bc('c', "c".into())] {
        assert_eq!(round_trip::<ByChar>(&u).unwrap(), u);
    }
    for u in [
        ByEnum::AppleCount(3),
        ByEnum::CherryName("pie".into()),
        ByEnum::Other(Fruit::Banana, true),
    ] {
        assert_eq!(round_trip::<ByEnum>(&u).unwrap(), u);
    }
    for u in [
        ByEnumImplicit::AppleCount(1),
        ByEnumImplicit::Default(Fruit::CherryPie),
    ] {
        assert_eq!(round_trip::<ByEnumImplicit>(&u).unwrap(), u);
    }
    assert_eq!(
        ByEnumImplicit::Default(Fruit::Banana).discriminator(),
        Fruit::Banana
    );
    let u = ByULongLong::Default(8);
    assert_eq!(round_trip::<ByULongLong>(&u).unwrap(), u);
    let u = WithArray::Cells([[1, 2], [3, 4]]);
    assert_eq!(round_trip::<WithArray>(&u).unwrap(), u);
    let o = Outer {
        nested: m::outer::Inner { v: 4 },
        switch_mode: m::outer::Mode::On,
    };
    assert_eq!(round_trip::<Outer>(&o).unwrap(), o);
    let e = Failure {
        code: 1,
        message: "m".into(),
        kind: Fruit::Apple,
    };
    assert_eq!(round_trip::<Failure>(&e).unwrap(), e);
}

#[test]
fn checks_on_sending() {
    let kind = |e: SystemException| e.kind();
    // A discriminator that is not a label of the member.
    assert_eq!(
        kind(Any::insert::<ByChar>(&ByChar::Bc('a', "x".into())).unwrap_err()),
        Some(SystemExceptionKind::BAD_PARAM)
    );
    // The default member with a label's discriminator.
    assert_eq!(
        kind(Any::insert::<ByEnum>(&ByEnum::Other(Fruit::Apple, true)).unwrap_err()),
        Some(SystemExceptionKind::BAD_PARAM)
    );
    assert_eq!(
        kind(Any::insert::<ByULongLong>(&ByULongLong::Default(7)).unwrap_err()),
        Some(SystemExceptionKind::BAD_PARAM)
    );
    let mut h = holder();
    h.tag = "too long a tag".into();
    assert_eq!(
        kind(Any::insert::<Holder>(&h).unwrap_err()),
        Some(SystemExceptionKind::BAD_PARAM)
    );
    let mut h = holder();
    h.ascii = 'é';
    assert_eq!(
        kind(Any::insert::<Holder>(&h).unwrap_err()),
        Some(SystemExceptionKind::DATA_CONVERSION)
    );
}

#[test]
fn typecodes_and_anys() {
    let tc = Holder::type_code();
    assert_eq!(tc.kind(), TCKind::Struct);
    assert_eq!(tc.id().unwrap(), "IDL:rustorb.org/RustMapping/Holder:1.0");
    assert_eq!(tc.member_name(13).unwrap(), "type");
    assert_eq!(tc.member_type(4).unwrap().kind(), TCKind::Alias);

    let a = Any::insert::<m::alias::Octets>(&[1, 2]).unwrap();
    assert_eq!(a.typecode().kind(), TCKind::Alias);
    assert_eq!(a.typecode().name().unwrap(), "Octets");
    assert_eq!(a.extract::<m::alias::Octets>(), Some(vec![1, 2]));
    // An alias and its content are equivalent.
    assert_eq!(a.extract::<idl::Sequence<idl::Octet>>(), Some(vec![1, 2]));
    assert_eq!(a.extract::<Pair>(), None);

    let a = Any::insert::<Fruit>(&Fruit::CherryPie).unwrap();
    assert_eq!(a.extract::<Fruit>(), Some(Fruit::CherryPie));
    assert_eq!(a.typecode().member_name(2).unwrap(), "CHERRY_PIE");
    assert_eq!(m::alias::Money::type_code().kind(), TCKind::Alias);
}

#[test]
fn valuetypes() {
    // Circle arrives where Shape is declared. Each test that relies on it
    // registers, as the tests run in any order.
    rust_mapping_idl::register_value_types();
    let s = Shape::new(ShapeState {
        name: "s".into(),
        secret: 1,
    });
    let c = Circle::new(CircleState {
        base: ShapeState {
            name: "c".into(),
            secret: 2,
        },
        radius: 1.5,
    });
    let as_shape: Shape = c.clone().into();
    assert_eq!(as_shape.get().name, "c");
    assert!(Circle::try_from(as_shape.clone()).is_ok());
    assert!(Circle::try_from(s.clone()).is_err());
    s.with_mut(|st| st.secret = 3);
    assert_eq!(s.with(|st| st.secret), 3);

    // Sharing through a struct, and a derived type where the base is.
    let d = Drawing {
        main: Some(as_shape.clone()),
        others: vec![Some(as_shape.clone()), Some(s.clone()), None],
        count: Some(LongBox::new(4)),
    };
    let back = round_trip::<Drawing>(&d).unwrap();
    let main = back.main.unwrap();
    assert!(main.ptr_eq(back.others[0].as_ref().unwrap()));
    assert_eq!(Circle::try_from(main).unwrap().get().radius, 1.5);
    assert_eq!(back.others[1].as_ref().unwrap().get().secret, 3);
    assert!(back.others[2].is_none());
    assert_eq!(*back.count.unwrap(), 4);

    // Cycles.
    let a = Link::new(LinkState { id: 1, next: None });
    let b = Link::new(LinkState {
        id: 2,
        next: Some(a.clone()),
    });
    a.with_mut(|st| st.next = Some(b.clone()));
    let a2 = round_trip::<Link>(&Some(a.clone())).unwrap().unwrap();
    let b2 = a2.get().next.unwrap();
    assert_eq!(b2.get().id, 2);
    assert!(b2.get().next.unwrap().ptr_eq(&a2));
    for v in [a, a2] {
        v.with_mut(|st| st.next = None);
    }

    let pb = PairBox::new(Pair {
        first: 1,
        second: 2,
    });
    let back = round_trip::<PairBox>(&Some(pb.clone())).unwrap().unwrap();
    assert_eq!(back.first, 1);
    assert_eq!(PairBox::type_code().kind(), TCKind::ValueBox);
}

// --- calls --------------------------------------------------------------

#[derive(Default)]
struct DerivedImpl {
    label: Mutex<String>,
    notes: Mutex<Vec<String>>,
    this: Mutex<Option<ObjectRef>>,
}

impl BaseServant for DerivedImpl {
    fn id(&self) -> Result<i32, SystemException> {
        Ok(42)
    }

    fn label(&self) -> Result<String, SystemException> {
        Ok(self.label.lock().unwrap().clone())
    }

    fn set_label(&self, value: &str) -> Result<(), SystemException> {
        *self.label.lock().unwrap() = value.to_owned();
        Ok(())
    }

    fn base_op(&self) -> Result<(), m::base::BaseOpError> {
        Err(m::base::BaseError { why: "why".into() }.into())
    }
}

impl DerivedServant for DerivedImpl {
    fn derived_op(&self, a: i32, b: &mut i32) -> Result<(i32, i32), m::derived::DerivedOpError> {
        match a {
            0 => Err(Empty {}.into()),
            1 => Err(Failure {
                code: 7,
                message: "failed".into(),
                kind: Fruit::Banana,
            }
            .into()),
            2 => Err(SystemException::new(
                SystemExceptionKind::NO_PERMISSION,
                0,
                rustorb_core::CompletionStatus::No,
            )
            .into()),
            _ => {
                *b += a;
                Ok((a * 2, a * 3))
            }
        }
    }

    fn notify(&self, msg: &str) -> Result<(), SystemException> {
        self.notes.lock().unwrap().push(msg.to_owned());
        Ok(())
    }

    fn as_base(&self) -> Result<Option<Base>, SystemException> {
        Ok(self
            .this
            .lock()
            .unwrap()
            .clone()
            .map(Base::unchecked_narrow))
    }

    fn laters(&self) -> Result<m::base::LaterSeq, SystemException> {
        Ok(vec![None])
    }

    fn get_value(&self, r#match: &str, pair: &mut Pair) -> Result<String, SystemException> {
        pair.first += 1;
        Ok(format!("{match}!"))
    }

    fn take(
        &self,
        h: &Holder,
        p: &Pair,
        f: Fruit,
        o: &[u8],
        l: Option<&Later>,
        x: Option<&ObjectRef>,
        a: &Any,
        money: &Money,
        g: &Grid,
    ) -> Result<(), SystemException> {
        let ok = *h == holder()
            && p.first == 1
            && f == Fruit::Apple
            && o == [1, 2]
            && l.is_none()
            && x.is_some()
            && a.extract::<idl::Long>() == Some(5)
            && money.to_string() == "1.25"
            && g == &[[1, 2], [3, 4]];
        if ok {
            Ok(())
        } else {
            Err(SystemException::new(
                SystemExceptionKind::BAD_PARAM,
                0,
                rustorb_core::CompletionStatus::No,
            ))
        }
    }
}

#[test]
fn calls() {
    let server = server_orb();
    let root = server.root_poa().unwrap();
    root.the_poa_manager().activate().unwrap();
    let servant = DerivedImpl::default();
    let (_, local) = DerivedPoa(servant).activate(&root).unwrap();
    let client = Orb::with_options(OrbOptions::default()).unwrap();
    let obj = remote(&client, &server, local.object());

    let d = Derived::narrow(&obj).unwrap().unwrap();
    assert!(Other::narrow(&obj).unwrap().is_none());
    assert_eq!(d.id().unwrap(), 42);
    d.set_label("hello").unwrap();
    assert_eq!(d.label().unwrap(), "hello");

    let mut b = 10;
    assert_eq!(d.derived_op(5, &mut b).unwrap(), (10, 15));
    assert_eq!(b, 15);
    match d.derived_op(1, &mut b) {
        Err(m::derived::DerivedOpError::Failure(f)) => {
            assert_eq!(
                (f.code, f.message.as_str(), f.kind),
                (7, "failed", Fruit::Banana)
            )
        }
        r => panic!("{r:?}"),
    }
    let e = d.derived_op(0, &mut b).unwrap_err();
    assert!(matches!(e, m::derived::DerivedOpError::Empty(_)));
    assert_eq!(e.repository_id(), Empty::REPOSITORY_ID);
    match d.derived_op(2, &mut b) {
        Err(m::derived::DerivedOpError::System(e)) => {
            assert!(e.is(SystemExceptionKind::NO_PERMISSION))
        }
        r => panic!("{r:?}"),
    }
    match d.base_op() {
        Err(m::base::BaseOpError::BaseError(e)) => assert_eq!(e.why, "why"),
        r => panic!("{r:?}"),
    }

    let mut pair = Pair {
        first: 1,
        second: 2,
    };
    assert_eq!(d.get_value("m", &mut pair).unwrap(), "m!");
    assert_eq!(pair.first, 2);
    assert_eq!(d.laters().unwrap(), vec![None]);
    assert!(d.as_base().unwrap().is_none());

    d.take(
        &holder(),
        &Pair {
            first: 1,
            second: 0,
        },
        Fruit::Apple,
        &[1, 2],
        None,
        Some(&obj),
        &Any::from(5i32),
        &"1.25".parse().unwrap(),
        &[[1, 2], [3, 4]],
    )
    .unwrap();
    let e = d
        .take(
            &holder(),
            &Pair {
                first: 0,
                second: 0,
            },
            Fruit::Apple,
            &[1, 2],
            None,
            None,
            &Any::from(5i32),
            &"1.25".parse().unwrap(),
            &[[1, 2], [3, 4]],
        )
        .unwrap_err();
    assert!(e.is(SystemExceptionKind::BAD_PARAM));

    d.notify("one").unwrap();
    // The base type of the reference, and the widening conversion.
    let base: Base = d.clone().into();
    assert_eq!(base.id().unwrap(), 42);
    assert!(obj.is_a(Base::REPOSITORY_ID).unwrap());

    // An unknown operation.
    let e = obj.request("no_such_op").invoke().unwrap_err();
    assert!(
        e.as_system()
            .unwrap()
            .is(SystemExceptionKind::BAD_OPERATION)
    );
    drop(client);
    server.shutdown(true).unwrap();
}

#[derive(Debug)]
struct CanvasImpl;

impl CanvasServant for CanvasImpl {
    fn echo_shape(&self, s: Option<&Shape>) -> Result<Option<Shape>, SystemException> {
        Ok(s.cloned())
    }

    fn echo_drawing(&self, d: &Drawing) -> Result<Drawing, SystemException> {
        Ok(d.clone())
    }

    fn echo_box(&self, b: Option<&LongBox>) -> Result<Option<LongBox>, SystemException> {
        Ok(b.cloned())
    }
}

#[test]
fn valuetype_calls() {
    rust_mapping_idl::register_value_types();
    let server = server_orb();
    let root = server.root_poa().unwrap();
    root.the_poa_manager().activate().unwrap();
    let servant: Arc<dyn Servant> = Arc::new(CanvasPoa(CanvasImpl));
    let id = root.activate_object(servant).unwrap();
    let client = Orb::with_options(OrbOptions::default()).unwrap();
    let obj = remote(&client, &server, &root.id_to_reference(&id).unwrap());
    let canvas = Canvas::unchecked_narrow(obj);

    let c = Circle::new(CircleState {
        base: ShapeState {
            name: "c".into(),
            secret: 2,
        },
        radius: 2.5,
    });
    let back = canvas.echo_shape(Some(&c.clone().into())).unwrap().unwrap();
    let back = Circle::try_from(back).unwrap();
    assert_eq!(back.get().radius, 2.5);
    assert_eq!(back.get().base.secret, 2);
    assert!(canvas.echo_shape(None).unwrap().is_none());

    let shape: Shape = c.into();
    let d = Drawing {
        main: Some(shape.clone()),
        others: vec![Some(shape)],
        count: None,
    };
    let back = canvas.echo_drawing(&d).unwrap();
    assert!(
        back.main
            .as_ref()
            .unwrap()
            .ptr_eq(back.others[0].as_ref().unwrap())
    );
    assert_eq!(
        *canvas.echo_box(Some(&LongBox::new(9))).unwrap().unwrap(),
        9
    );
    drop(client);
    server.shutdown(true).unwrap();
}
